import{c as t,Q as o,j as a,m as n}from"./chunks/framework.BXc4yaFE.js";const p=JSON.parse('{"title":"Stop prompting, start looping: the Boris Cherny method","description":"","frontmatter":{"url":"https://x.com/Serantych/status/2072704742636003836","title":"Stop prompting, start looping: the Boris Cherny method","author":"Serantych","archived":"2026-07-20T00:00:00.000Z","handle":"@Serantych","published":"2026-07-02T00:00:00.000Z","stats":"122 likes · 15 retweets · 548 bookmarks · 1113333 views","tags":["claude-code","loop-engineering","compound-engineering","subagent-strategy","verification"],"type":"twitter-article"},"headers":[],"relativePath":"research/tweets/2026-07-02-@Serantych-003836.md","filePath":"research/tweets/2026-07-02-@Serantych-003836.md","lastUpdated":1785909234000}'),s={name:"research/tweets/2026-07-02-@Serantych-003836.md"};function i(r,e,h,l,d,u){return o(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="stop-prompting-start-looping-the-boris-cherny-method-—-serantych" tabindex="-1">Stop prompting, start looping: the Boris Cherny method — @Serantych <a class="header-anchor" href="#stop-prompting-start-looping-the-boris-cherny-method-—-serantych" aria-label="Permalink to &quot;Stop prompting, start looping: the Boris Cherny method — @Serantych&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/Serantych/status/2072704742636003836" target="_blank" rel="noreferrer">https://x.com/Serantych/status/2072704742636003836</a><strong>作者</strong>：Serantych（@Serantych） <strong>發布日期</strong>：2026-07-02 <strong>收錄日期</strong>：2026-07-20 <strong>類型</strong>：Twitter Article <strong>統計</strong>：122 likes · 15 retweets · 548 bookmarks · 1113333 views</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><h2 id="everyone-is-optimizing-their-prompts-boris-cherny-threw-the-whole-idea-out" tabindex="-1">Everyone is optimizing their prompts. Boris Cherny threw the whole idea out. <a class="header-anchor" href="#everyone-is-optimizing-their-prompts-boris-cherny-threw-the-whole-idea-out" aria-label="Permalink to &quot;Everyone is optimizing their prompts. Boris Cherny threw the whole idea out.&quot;">​</a></h2><h2 id="he-built-claude-code-he-runs-the-team-and-he-uses-the-tool-in-a-way-that-looks-nothing-like-how-most-people-use-it-no-secret-model-no-exotic-config-he-says-it-works-great-out-of-the-box-and-barely-customizes-it-the-leverage-is-not-in-the-tool-it-is-in-how-he-wraps-his-entire-day-around-it-here-is-the-part-that-breaks-people-s-brains-his-personal-setup-is-almost-boring-five-terminal-tabs-a-text-file-a-few-slash-commands-one-rule-he-repeats-more-than-any-other-put-together-they-let-one-engineer-behave-like-a-full-team-this-is-the-actual-method-pulled-from-his-own-january-workflow-thread-the-lenny-and-pragmatic-engineer-interviews-and-fortune-s-reporting-no-theory-just-what-he-does" tabindex="-1">He built Claude Code. He runs the team. And he uses the tool in a way that looks nothing like how most people use it. No secret model. No exotic config - he says it works great out of the box and barely customizes it. The leverage is not in the tool. It is in how he wraps his entire day around it. Here is the part that breaks people&#39;s brains: his personal setup is almost boring. Five terminal tabs. A text file. A few slash commands. One rule he repeats more than any other. Put together, they let one engineer behave like a full team. This is the actual method, pulled from his own January workflow thread, the Lenny and Pragmatic Engineer interviews, and Fortune&#39;s reporting. No theory. Just what he does. <a class="header-anchor" href="#he-built-claude-code-he-runs-the-team-and-he-uses-the-tool-in-a-way-that-looks-nothing-like-how-most-people-use-it-no-secret-model-no-exotic-config-he-says-it-works-great-out-of-the-box-and-barely-customizes-it-the-leverage-is-not-in-the-tool-it-is-in-how-he-wraps-his-entire-day-around-it-here-is-the-part-that-breaks-people-s-brains-his-personal-setup-is-almost-boring-five-terminal-tabs-a-text-file-a-few-slash-commands-one-rule-he-repeats-more-than-any-other-put-together-they-let-one-engineer-behave-like-a-full-team-this-is-the-actual-method-pulled-from-his-own-january-workflow-thread-the-lenny-and-pragmatic-engineer-interviews-and-fortune-s-reporting-no-theory-just-what-he-does" aria-label="Permalink to &quot;He built Claude Code. He runs the team. And he uses the tool in a way that looks nothing like how most people use it. No secret model. No exotic config - he says it works great out of the box and barely customizes it. The leverage is not in the tool. It is in how he wraps his entire day around it.
Here is the part that breaks people&#39;s brains: his personal setup is almost boring. Five terminal tabs. A text file. A few slash commands. One rule he repeats more than any other. Put together, they let one engineer behave like a full team.
This is the actual method, pulled from his own January workflow thread, the Lenny and Pragmatic Engineer interviews, and Fortune&#39;s reporting. No theory. Just what he does.&quot;">​</a></h2><h2 id="part-1-he-runs-an-orchestra-not-a-chat" tabindex="-1">PART 1 - HE RUNS AN ORCHESTRA, NOT A CHAT <a class="header-anchor" href="#part-1-he-runs-an-orchestra-not-a-chat" aria-label="Permalink to &quot;PART 1 - HE RUNS AN ORCHESTRA, NOT A CHAT&quot;">​</a></h2><p>Five local, ten on the web, and one kicked off from his phone in bed. Most people run one Claude and wait for it. Boris runs a swarm. Five Claude Code sessions live in his MacBook terminal, tabs numbered 1 through 5, with system notifications telling him which one needs input. On top of that, 5 to 10 more run on the web at claude.ai/code. He hands sessions off from local to web, teleports them back with --teleport, and starts fresh ones from the Claude iOS app first thing in the morning - before he is even at a desk. One detail most people get wrong: each local session gets its own git checkout, not a branch, not a worktree. That is how five agents edit the same repo at once without stepping on each other.</p><h2 id="quote" tabindex="-1">QUOTE: <a class="header-anchor" href="#quote" aria-label="Permalink to &quot;QUOTE:&quot;">​</a></h2><ul><li>&quot;I don&#39;t prompt Claude anymore. I have loops that are running. They&#39;re the ones that are prompting Claude and figuring out what to do. My job is to write loops.&quot;</li><li>Boris Cherny [圖 1 — 來源: caption: 5 local + 5-10 web + phone. Separate git checkouts. One human conducting. ] He is honest about the mess: 10 to 20 percent of those sessions get abandoned when they hit something unexpected. That is fine. When you run twenty, throwing away three costs nothing. And he does not model-shop. Opus with thinking, for everything - even though it is bigger and slower per token. You steer it less, it is better at tool use, and across a whole task it wins. When you are orchestrating ten sessions, per-session speed stops mattering. You are never the one waiting.</li></ul><h2 id="callout" tabindex="-1">CALLOUT: <a class="header-anchor" href="#callout" aria-label="Permalink to &quot;CALLOUT:&quot;">​</a></h2><ul><li>The bottleneck is no longer typing code. It is context switching between the agents writing it.</li></ul><hr><h2 id="part-2-compound-engineering-the-text-file-that-learns" tabindex="-1">PART 2 - COMPOUND ENGINEERING: THE TEXT FILE THAT LEARNS <a class="header-anchor" href="#part-2-compound-engineering-the-text-file-that-learns" aria-label="Permalink to &quot;PART 2 - COMPOUND ENGINEERING: THE TEXT FILE THAT LEARNS&quot;">​</a></h2><p>Every mistake becomes a rule. The rule is shared. The team gets smarter every week. Boris&#39;s memory system is a plain text file called CLAUDE.md, checked into git. Not a vector database. Not a fine-tune. A file every Claude reads at the start of every session. The twist is that it is a team object. His whole team writes to one shared CLAUDE.md multiple times a week. Anytime Claude does something wrong, the correction goes into the file so it never happens again. It holds style conventions, design guidelines, the PR template, the landmines.</p><h2 id="quote-1" tabindex="-1">QUOTE: <a class="header-anchor" href="#quote-1" aria-label="Permalink to &quot;QUOTE:&quot;">​</a></h2><ul><li>&quot;Anytime Claude does something incorrectly, we add it to the CLAUDE.md so it knows not to do it next time.&quot;</li><li>Boris Cherny [圖 2 — 來源: Human spots the issue once. Claude writes the rule. Every future session avoids it. ] His own personal CLAUDE.md? Basically two lines, pointing at the team&#39;s shared one. The team file sits around 2,500 tokens - deliberately lean, because he knows exactly how expensive a bloated one gets (more on that later). The sharpest move is in code review. When Boris reviews a teammate&#39;s PR and spots an anti-pattern, he does not just leave a comment. He tags Claude on the PR through the GitHub Action and has it write the lesson straight into CLAUDE.md as part of that same PR. The fix and the rule ship together. This is what people mean by compound engineering: the codebase itself gets more intelligent with every merge.</li></ul><hr><h2 id="part-3-plan-first-then-get-out-of-the-way" tabindex="-1">PART 3 - PLAN FIRST, THEN GET OUT OF THE WAY <a class="header-anchor" href="#part-3-plan-first-then-get-out-of-the-way" aria-label="Permalink to &quot;PART 3 - PLAN FIRST, THEN GET OUT OF THE WAY&quot;">​</a></h2><p>The one-shot is a lie. The plan is the work. When people watch Claude &quot;one-shot&quot; a feature and fail, they blame the model. Boris blames the missing plan. His default is Plan mode - Shift+Tab twice. He does not let Claude touch code yet. He goes back and forth on the plan until it matches what is in his head. Only then does he flip to auto-accept edits and let it run.</p><h2 id="quote-2" tabindex="-1">QUOTE: <a class="header-anchor" href="#quote-2" aria-label="Permalink to &quot;QUOTE:&quot;">​</a></h2><ul><li>&quot;If my goal is to write a Pull Request, I will use Plan mode, and go back and forth with Claude until I like its plan. From there, I switch into auto-accept edits mode and Claude can usually 1-shot it. A good plan is really important!&quot;</li><li>Boris Cherny [圖 3 — 來源: Plan mode -&gt; agree on the plan -&gt; auto-accept -&gt; one-shot. The plan is where the thinking lives.] The reason one-shots fail for most people is bandwidth. You described a complex feature in a few words, so Claude built a different feature than the one in your head. Planning is how you raise the bandwidth before a single line is written. The &quot;magic one-shot&quot; is just a good plan cashing out.</li></ul><hr><h2 id="part-4-the-inner-loop-turned-into-code" tabindex="-1">PART 4 - THE INNER LOOP, TURNED INTO CODE <a class="header-anchor" href="#part-4-the-inner-loop-turned-into-code" aria-label="Permalink to &quot;PART 4 - THE INNER LOOP, TURNED INTO CODE&quot;">​</a></h2><p>Anything he does more than twice becomes a command, a subagent, or a hook. This is where the &quot;vanilla setup&quot; quietly becomes a machine. Boris does not re-prompt for routine work. He encodes it. Slash commands for every inner-loop task, checked into .claude/commands/ so the whole team and Claude itself can use them. His workhorse is /commit-push-pr, run dozens of times a day. It uses inline bash to precompute git status up front, so the model does not waste a round trip figuring out state. Subagents to protect context. Two he leans on: a Code Simplifier that cleans up after Claude finishes, and a Verify App agent with detailed instructions for testing end to end. A subagent runs, returns just the result, and keeps the mess out of his main session. A PostToolUse hook that auto-formats every edit (bun run format). Claude&#39;s code is already clean; the hook handles the last 10 percent so nothing trivial breaks CI later. Permissions instead of danger. He almost never uses --dangerously-skip-permissions. Instead he allowlists safe commands with /permissions (bun run build, bun run test, and friends), checked into .claude/settings.json and shared with the team. Everyone agrees on the safe defaults once. MCP for the rest of his tools. Claude posts to Slack, runs BigQuery for analytics, pulls errors from Sentry - all through MCP, all configured in git. His warning: MCPs bloat your context and open a prompt-injection door, so have Claude review an MCP before you install it. [圖 4 — 來源: Slash commands, subagents, hooks, permissions, MCP. The routine work stops being prompted and starts being infrastructure.]</p><h2 id="callout-1" tabindex="-1">CALLOUT: <a class="header-anchor" href="#callout-1" aria-label="Permalink to &quot;CALLOUT:&quot;">​</a></h2><ul><li>Boris&#39;s rule of thumb: anytime you do a task, build the thing that will do it for you next time. Intent compounds. Prompting does not.</li></ul><hr><h2 id="part-5-verification-is-the-whole-game" tabindex="-1">PART 5 - VERIFICATION IS THE WHOLE GAME <a class="header-anchor" href="#part-5-verification-is-the-whole-game" aria-label="Permalink to &quot;PART 5 - VERIFICATION IS THE WHOLE GAME&quot;">​</a></h2><p>is single most important tip, and it is not about prompting at all. If you take one thing from how Boris works, take this: give the model a way to check its own work, and it will grind until the work is actually good.</p><h2 id="quote-3" tabindex="-1">QUOTE: <a class="header-anchor" href="#quote-3" aria-label="Permalink to &quot;QUOTE:&quot;">​</a></h2><ul><li>&quot;Claude tests every single change I land to claude.ai/code using the Claude Chrome extension. It opens a browser, tests the UI, and iterates until the code works and the UX feels good.&quot;</li><li>Boris Cherny [圖 5 — 來源: No gate = the agent agrees with itself. A real check = 2-3x the quality. ] A real feedback loop - a test suite, a type check, a build, a browser, a simulator - improves the final result by a factor of 2 to 3. Without it you do not have a loop. You have an agent grading its own homework and passing itself every time. For long-running work, he layers the verification: prompt a background agent to check the result when the main one finishes, use an agent-stop hook for a deterministic gate, or run an autonomous looping plugin for the fully hands-off case. The point is the same at every scale - the loop only advances when reality says it did. The payoff shows up in how his team spends its time. Because verification runs inside the loop, humans are freed to do the two things machines still cannot: review and steer. By the time an engineer opens a PR, the code is already in good shape.</li></ul><hr><h2 id="part-6-tokenmaxxing-done-with-eyes-open" tabindex="-1">PART 6 - TOKENMAXXING, DONE WITH EYES OPEN <a class="header-anchor" href="#part-6-tokenmaxxing-done-with-eyes-open" aria-label="Permalink to &quot;PART 6 - TOKENMAXXING, DONE WITH EYES OPEN&quot;">​</a></h2><p>Spend more tokens. Just not the wasted ones. Boris&#39;s advice to companies sounds reckless until you hear the second half.</p><h2 id="quote-4" tabindex="-1">QUOTE: <a class="header-anchor" href="#quote-4" aria-label="Permalink to &quot;QUOTE:&quot;">​</a></h2><ul><li>&quot;Don&#39;t try to cost cut at the beginning. Give engineers as many tokens as possible.&quot;</li><li>Boris Cherny [圖 6 — 來源: Max the tokens that buy capability. Cut the ones lost to context bloat and re-read history.] He calls it tokenmaxxing. The bottleneck was never the cost of tokens - it is how fast engineers learn to use them well. Cap usage and you throttle the learning. And the number you should compare Claude Code to is not a 20-dollar coding assistant. It is what an engineer would have cost to do the same work. That is the benchmark. But &quot;spend more&quot; is not the same as &quot;spend blind.&quot; In a podcast breakdown, Boris walked through how tokens get burned before the model even reads your prompt - a big chunk lost to a bloated CLAUDE.md, another chunk paid to re-read old history. That is exactly why his own team file is a lean 2,500 tokens and his personal one is two lines. He maxes the spend that buys learning and cuts the spend that buys nothing.</li></ul><hr><h2 id="part-7-the-honest-part" tabindex="-1">PART 7 - THE HONEST PART <a class="header-anchor" href="#part-7-the-honest-part" aria-label="Permalink to &quot;PART 7 - THE HONEST PART&quot;">​</a></h2><p>What the method does not fix. None of this deletes the engineer. It moves him. 10 to 20 percent of Boris&#39;s sessions get abandoned. His code review became the new bottleneck the moment code-writing stopped being one. And the faster the swarm ships code nobody hand-wrote, the wider the gap between what is in the repo and what any human actually understands. A smooth workflow charges compound interest on that gap. The day you have to debug a system no one has read costs more than the tokens ever did. Two engineers can run this exact setup and get opposite outcomes. One uses it to move faster on work they understand deeply. The other uses it to stop understanding the work at all. The tool cannot tell the difference. You can. [圖 7 — 來源: Same five tabs, same CLAUDE.md, same commands. One path is leverage. The other is surrender.] Boris stopped writing code by hand. He stopped prompting turn by turn. He did not stop planning, reviewing, or steering - the parts that are actually him. That is the method. Not better prompts. A better position: out of the typing, into the judgment.</p><hr><h2 id="研究摘要" tabindex="-1">研究摘要 <a class="header-anchor" href="#研究摘要" aria-label="Permalink to &quot;研究摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：Boris Cherny（Claude Code 負責人）的個人工作法：多平行 session（各自獨立 git checkout）、CLAUDE.md 為團隊共筆記憶、Plan mode 先行、驗證迴圈提升 2-3 倍品質、tokenmaxxing 但砍浪費 token。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ul><li>平行編排取代單一對話：本機 5 個 terminal tab + web 5-10 個 + 手機啟動，各自獨立 git checkout（非 branch/worktree）避免衝突；10-20% session 放棄視為正常成本</li><li>Compound Engineering：CLAUDE.md 是團隊共筆物件而非個人筆記，任何錯誤都寫入規則；code review 發現 anti-pattern 時透過 GitHub Action 讓 Claude 把教訓直接寫進 CLAUDE.md，fix 與 rule 同一 PR 出貨</li><li>Plan mode 先行：不讓 Claude 碰程式碼直到 plan 對齊腦中想法才 auto-accept；one-shot 失敗多半是描述 bandwidth 不足而非模型問題</li><li>內迴圈編碼化：重複兩次以上的工作變成 slash command / subagent / hook；subagent 用於保護 context（Code Simplifier、Verify App agent）；PostToolUse hook 自動格式化；permissions allowlist 取代 <code>--dangerously-skip-permissions</code></li><li>驗證是全部關鍵：給模型自我檢查機制（test/type-check/build/browser/simulator）可提升結果品質 2-3 倍；長任務用 background agent 檢查、agent-stop hook 做 deterministic gate</li></ul><h3 id="關鍵數據-工具" tabindex="-1">關鍵數據 / 工具 <a class="header-anchor" href="#關鍵數據-工具" aria-label="Permalink to &quot;關鍵數據 / 工具&quot;">​</a></h3><ul><li>統計：122 likes・15 retweets・548 bookmarks・1,113,333 views</li><li>來源交叉驗證：Boris Cherny 本人 January workflow thread + Lenny/Pragmatic Engineer 訪談 + Fortune 報導</li><li>具體工具：<code>--teleport</code>（session 本機/web 交接）、<code>/commit-push-pr</code>、Code Simplifier subagent、Verify App agent、PostToolUse hook、<code>.claude/settings.json</code> permissions allowlist、Claude Chrome extension 自動化瀏覽器測試</li><li>CLAUDE.md 團隊檔案約 2,500 tokens；個人檔案僅 2 行指向團隊檔案</li></ul><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ul><li>多來源引用（推文串+訪談+報導）交叉驗證，證據品質優於單一二手轉述；仍為整理性文章，未附原始逐字連結供核對</li><li>Part 7「誠實的部分」揭露副作用：code review 成為新瓶頸、repo 與人類理解的落差擴大——罕見的自我批判段落，提升整篇文章可信度</li><li>tokenmaxxing 論述（先給足 token 再砍浪費而非一開始就省）與 workspace「CJK 稅對策：內部可英文、對使用者仍繁中」的效率非目標本身判斷一致，可作外部獨立驗證引用</li></ul><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>9/10</td><td>平行 session git checkout 隔離、PR 時 CLAUDE.md 修正、agent-stop deterministic gate 皆可直接對照 workspace 既有實踐</td></tr><tr><td>B. 創新性 (20%)</td><td>7/10</td><td>loop-over-prompt 非新概念，但具體戰術細節（獨立 git checkout、PR-time CLAUDE.md 修正）較少見</td></tr><tr><td>C. 證據品質 (20%)</td><td>8/10</td><td>三方獨立來源交叉引用（推文串/訪談/報導），具名引言，證據品質優於同類文章</td></tr><tr><td>D. 技術深度 (15%)</td><td>8/10</td><td><code>--teleport</code>/PostToolUse hook/agent-stop gate/settings.json allowlist 等具體技術細節</td></tr><tr><td>E. 泛化性 (15%)</td><td>8/10</td><td>適用任何 Claude Code 團隊實踐，非產品推廣文</td></tr><tr><td><strong>加權總分</strong></td><td><strong>8.1/10</strong></td><td>A×0.3+B×0.2+C×0.2+D×0.15+E×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Rule <strong>理由</strong>：多項具體戰術（獨立 git checkout 平行隔離、PR-time CLAUDE.md 修正流程、驗證迴圈 2-3x 品質倍增）可補強 subagent-strategy.md 與 core.md 既有規則</p>`,53)])])}const m=t(s,[["render",i]]);export{p as __pageData,m as default};
